-- Account-scoped D1 storage. Authentication remains in Supabase.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS workspace_onboarding_invites(user_id TEXT NOT NULL,client_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,submitted_at TEXT,guard INTEGER NOT NULL DEFAULT 1 CHECK(guard=1),PRIMARY KEY(user_id,client_id));
CREATE TABLE IF NOT EXISTS workspace_onboarding_submissions(user_id TEXT NOT NULL,client_id TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(user_id,client_id));
CREATE TABLE IF NOT EXISTS workspace_accounts (user_id TEXT PRIMARY KEY, revision TEXT NOT NULL, ready INTEGER NOT NULL DEFAULT 0, guard INTEGER NOT NULL DEFAULT 1 CHECK(guard=1));
CREATE TABLE IF NOT EXISTS workspace_settings (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, name TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,name));
CREATE TABLE IF NOT EXISTS workspace_applications (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_applications_position ON workspace_applications(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_to_apply (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_to_apply_position ON workspace_to_apply(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_daily_tasks (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_daily_tasks_position ON workspace_daily_tasks(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_client_tasks (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_client_tasks_position ON workspace_client_tasks(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_social_trends (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_social_trends_position ON workspace_social_trends(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_emails (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_emails_position ON workspace_emails(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_deleted_gmail_ids (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_deleted_gmail_ids_position ON workspace_deleted_gmail_ids(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_alerts (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_alerts_position ON workspace_alerts(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_cleared_notification_keys (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_cleared_notification_keys_position ON workspace_cleared_notification_keys(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_onboarding_submission_ids (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_onboarding_submission_ids_position ON workspace_onboarding_submission_ids(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_email_templates (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_email_templates_position ON workspace_email_templates(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_personal_documents (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_personal_documents_position ON workspace_personal_documents(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_invoices (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_invoices_position ON workspace_invoices(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_scripts (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_scripts_position ON workspace_scripts(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_work_links (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_work_links_position ON workspace_work_links(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_wallet_entries (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_wallet_entries_position ON workspace_wallet_entries(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_subscriptions (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_subscriptions_position ON workspace_subscriptions(user_id,position);
CREATE TABLE IF NOT EXISTS workspace_account_sign_in_history (user_id TEXT NOT NULL REFERENCES workspace_accounts(user_id) ON DELETE CASCADE, id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS workspace_account_sign_in_history_position ON workspace_account_sign_in_history(user_id,position);
